"""Targeted startup regressions over real HTTP/storage locks. No permission bypass or world injection."""
import json,time,unittest,argparse
from pathlib import Path
from test_drone_remote import DroneRemote
from test_continuity import RecordedResult
class BootHotfix(DroneRemote):
 def raw_page(self):
  c=self.browser.new_context(viewport={'width':1280,'height':900});self.contexts.append(c);p=c.new_page();c.add_init_script('window.__icarusSeed=10101;');return p
 def test_boot_departed_server_lease_waits_then_resolves_without_reloading_or_bypassing(self):
  p=self.raw_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');self.assertTrue(p.evaluate('__icarusSoak.save()'));self.m.BRIDGE_SERVICE=self.m.BridgeService();prior=self.m.BRIDGE_SERVICE.claim('departed-host-lease');p.reload();p.wait_for_function('ICARUSBoot.complete');self.assertIn('WAITING FOR WRITER',p.locator('.boot-status').inner_text());self.assertEqual(p.evaluate('ICARUSBoot.states.authorization.state'),'ready');self.assertFalse(p.evaluate('ICARUSHost.canWrite()'));self.assertEqual(self.m.BRIDGE_SERVICE.owner,'departed-host-lease');p.locator('#boot-auth-code').fill('still-entering');before=p.evaluate('__icarusSoak.snapshot()');self.assertEqual(before['tick'],0)
  p.wait_for_function('ICARUSHost.canWrite()&&ICARUSDurable.canWrite()',timeout=20000);self.assertGreater(self.m.BRIDGE_SERVICE.generation,prior['generation']);self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertEqual(p.locator('#boot-auth-code').input_value(),'still-entering');self.assertTrue(p.locator('#boot-auth-code').evaluate('e=>e===document.activeElement'));self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden());self.assertFalse(p.evaluate('document.getElementById("icarus-main").inert'));self.assertTrue(p.evaluate('__icarusSoak.save()'));p.reload();p.wait_for_function('ICARUSBoot.complete');self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertTrue(p.locator('#icarus-boot').is_visible())
 def test_boot_delayed_asset_keeps_input_until_actual_initialization_and_explicit_entry(self):
  p=self.raw_page();held=[];p.route('**/drone-ops.js',lambda r:held.append(r));p.goto(self.url+'/icarus.html?icarus_soak=1',wait_until='commit');p.locator('#boot-auth-code').fill('unfinished-key');p.wait_for_timeout(8000);self.assertFalse(p.evaluate('ICARUSBoot.complete'));self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertNotIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertTrue(p.locator('.boot-observe').is_disabled());self.assertEqual(p.locator('#boot-auth-code').input_value(),'unfinished-key');self.assertTrue(held)
  for route in held:route.continue_()
  p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertEqual(p.locator('#boot-auth-code').input_value(),'unfinished-key');p.keyboard.press('Escape');self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())
 def test_boot_authorization_failure_and_retry_are_separate_from_writer_ownership(self):
  p=self.raw_page();held=[];p.route('**/api/icarus/bootstrap',lambda r:held.append(r));p.goto(self.url+'/icarus.html?icarus_soak=1',wait_until='domcontentloaded');p.locator('#boot-auth-code').fill('wrong');p.locator('.boot-auth button').click();p.wait_for_function('document.querySelector(".boot-auth-result").textContent.includes("rejected")');self.assertEqual(p.evaluate('ICARUSBoot.states.authorization.state'),'failed');self.assertFalse(p.evaluate('ICARUSHost.canWrite()'));self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertEqual(p.locator('#boot-auth-code').input_value(),'wrong');p.locator('#boot-auth-code').fill('test-host');p.locator('.boot-auth button').click();p.wait_for_function('document.querySelector(".boot-auth-result").textContent.includes("Verified")');self.assertEqual(p.evaluate('ICARUSBoot.states.authorization.state'),'ready');self.assertFalse(p.evaluate('ICARUSBoot.complete'));self.assertNotIn('ICARUS ONLINE',p.locator('.boot-status').inner_text())
  for route in held:route.continue_()
  p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())
 def test_boot_live_owner_is_never_stolen_and_lost_generation_never_reclaims(self):
  self.m.BRIDGE_SERVICE.claim('live-owner-fixture');p=self.raw_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete');self.m.BRIDGE_SERVICE.heartbeat('live-owner-fixture',self.m.BRIDGE_SERVICE.generation);p.wait_for_timeout(4200);self.assertEqual(self.m.BRIDGE_SERVICE.owner,'live-owner-fixture');self.assertFalse(p.evaluate('ICARUSHost.canWrite()'));self.assertEqual(p.evaluate('__icarusSoak.time()'),0);self.assertEqual(p.evaluate('ICARUSBoot.states.authorization.state'),'ready')
 def test_boot_initialization_error_retry_keeps_existing_voyage(self):
  p=self.raw_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');before=p.evaluate('__icarusSoak.snapshot()');self.assertTrue(p.evaluate('__icarusSoak.save()'));p.route('**/drone-ops.js',lambda r:r.abort());p.reload();p.wait_for_function('document.querySelector(".boot-status").textContent.includes("FAILED")');self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertTrue(p.locator('.boot-retry').is_enabled());self.assertIn('drone',p.locator('.boot-stages').inner_text().lower());self.assertTrue(p.locator('.boot-observe').is_disabled());p.unroute('**/drone-ops.js');p.locator('.boot-retry').click();p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())

 def test_boot_lost_held_generation_is_fenced_even_after_other_owner_expires(self):
  p=self.raw_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');generation=p.evaluate('ICARUSHost.generation');before=p.evaluate('__icarusSoak.snapshot()');self.m.BRIDGE_SERVICE.expires=time.monotonic()-1;lease=self.m.BRIDGE_SERVICE.claim('replacement-owner-fixture');p.evaluate('ICARUSHost.request("host/heartbeat",{}).catch(e=>ICARUSHost.failed(e))');self.assertTrue(p.evaluate('ICARUSHost.lost'));self.assertEqual(p.evaluate('ICARUSBoot.states.authorization.state'),'ready');p.evaluate('ICARUSHost.acquire()');p.wait_for_timeout(2300);self.assertEqual(self.m.BRIDGE_SERVICE.owner,'replacement-owner-fixture');self.assertEqual(p.evaluate('ICARUSHost.generation'),generation);self.assertFalse(p.evaluate('ICARUSHost.canWrite()'));self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertIn('OWNERSHIP LOST',p.locator('.boot-status').inner_text());self.assertGreater(lease['generation'],generation)
 def test_boot_real_storage_completion_delay_keeps_key_and_writer_pending(self):
  p=self.raw_page();p.context.add_init_script("""const open=indexedDB.open.bind(indexedDB);indexedDB.open=(...args)=>{const req=open(...args),d=Object.getOwnPropertyDescriptor(IDBRequest.prototype,'onsuccess');Object.defineProperty(req,'onsuccess',{set(fn){d.set.call(req,e=>{window.releaseActualStorageCompletion=()=>fn.call(req,e);});}});return req;};""");p.goto(self.url+'/icarus.html?icarus_soak=1',wait_until='domcontentloaded');p.wait_for_function('typeof releaseActualStorageCompletion==="function"');p.locator('#boot-auth-code').fill('test-host');p.locator('.boot-auth button').click();p.wait_for_function('ICARUSBoot.states.authorization.state==="ready"');p.wait_for_timeout(2500);self.assertIn('WAITING FOR WRITER',p.locator('.boot-status').inner_text());self.assertFalse(p.evaluate('ICARUSDurable.canWrite()'));self.assertFalse(p.evaluate('ICARUSHost.canWrite()'));self.assertFalse(p.evaluate('ICARUSBoot.complete'));self.assertEqual(p.locator('#boot-auth-code').input_value(),'test-host');p.evaluate('releaseActualStorageCompletion()');p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()&&ICARUSDurable.canWrite()');self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertNotIn('waiting',p.locator('.boot-auth-result').inner_text());self.assertEqual(p.locator('#boot-auth-code').input_value(),'test-host');p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())
 def test_boot_bootstrap_error_is_actual_and_valid_key_recovers_without_reset(self):
  p=self.raw_page();p.route('**/api/icarus/bootstrap',lambda r:r.fulfill(status=503,content_type='application/json',body='{"error":"Actual delayed startup service fixture"}'));p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete');self.assertIn('Actual delayed startup service fixture',p.locator('.boot-stages').inner_text());self.assertIn('DISCONNECTED',p.locator('.boot-status').inner_text());before=p.evaluate('__icarusSoak.snapshot()');p.locator('#boot-auth-code').fill('test-host');p.locator('.boot-auth button').click();p.wait_for_function('ICARUSHost.canWrite()');self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertTrue(p.locator('#icarus-boot').is_visible());p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden())

