 ap=argparse.ArgumentParser();ap.add_argument('--report',type=Path,required=True);ap.add_argument('--case');ap.add_argument('--runtime',type=Path);a=ap.parse_args();
 if a.runtime:
  import test_umbra_browser
  test_umbra_browser.ROOT=a.runtime.resolve()
 names=[a.case] if a.case else [n for n in unittest.defaultTestLoader.getTestCaseNames(BootHotfix) if n.startswith('test_boot_')];r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.TestSuite(BootHotfix(n) for n in names));a.report.parent.mkdir(parents=True,exist_ok=True);a.report.write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d} for t,d in r.failures],'errors':[{'test':str(t),'detail':d} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
